insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Cosa serve per prenotare un tavolo?', $q9ghyfm$["cosa serve per prenotare","che dati servono per prenotare","cosa devo dire per prenotare","come si prenota un tavolo"]$q9ghyfm$::jsonb, 'Per prenotare servono in genere il numero di persone, il giorno, pranzo o cena (o l''orario) e un nome. È utile indicare subito anche eventuali allergie, seggioloni o altre esigenze particolari.', $q4l96ak${}$q4l96ak$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Conviene prenotare nel weekend?', $q0ajivx$["serve prenotare nel weekend","bisogna prenotare il sabato sera","conviene prenotare","meglio prenotare"]$q0ajivx$::jsonb, 'In genere nei fine settimana, nei giorni festivi e per gruppi è consigliabile prenotare con anticipo; le regole di questo locale vanno però verificate con il locale stesso.', $q3fwe5j${}$q3fwe5j$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Cosa sono i coperti?', $qaj9l1p$["cosa significa coperti","cosa sono i coperti","che vuol dire coperti","cosa vuol dire coperto"]$qaj9l1p$::jsonb, 'I "coperti" sono i posti a sedere, cioè il numero di persone sedute al tavolo; il "coperto" è invece la voce che alcuni locali applicano per ciascun commensale. Se previsto, deve essere indicato nel menu.', $qk3kz1x${}$qk3kz1x$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Cosa succede se sono in ritardo?', $q27y07s$["faccio ritardo cosa succede","se arrivo in ritardo il tavolo resta","quanto ritardo posso fare","se facciamo tardi"]$q27y07s$::jsonb, 'In caso di ritardo è importante avvisare il locale il prima possibile: il tempo per cui il tavolo viene tenuto è stabilito dal locale.', $qc91xgu${}$qc91xgu$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Cos''è una caparra?', $q99323k$["cosa e la caparra","a cosa serve la caparra","perche chiedono la caparra","cos e la caparra"]$q99323k$::jsonb, 'Alcuni locali chiedono una caparra o una garanzia (per esempio per gruppi o in date molto richieste). Se prevista, importo e condizioni sono stabiliti dal locale.', $qu60m0f${}$qu60m0f$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Si prenota con i bambini piccoli?', $qlno09r$["prenotare con bambini","devo contare i bambini nella prenotazione","i bambini si contano nei coperti","bambini piccoli prenotazione"]$qlno09r$::jsonb, 'Conviene indicare anche i bambini nel numero di persone e dire se serve un seggiolone, così il locale può organizzare il tavolo.', $q2dnegw${}$q2dnegw$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_locale', 'Come richiedo un seggiolone?', $qsz5oo0$["serve il seggiolone","come chiedo il seggiolone","si puo avere un seggiolone","seggiolone per bambini prenotazione"]$qsz5oo0$::jsonb, 'Se serve un seggiolone conviene segnalarlo già in fase di prenotazione, così il locale può prepararsi. La disponibilità dipende dal locale.', $qieovjn${}$qieovjn$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_locale', 'Posso portare il cane al ristorante?', $qurc8ci$["si possono portare i cani al ristorante","i cani sono ammessi nei ristoranti","posso entrare con il cane","animali ammessi"]$qurc8ci$::jsonb, 'L''ammissione degli animali dipende dalle scelte di ogni locale: alcuni li accolgono, altri no, o solo in alcune aree. Conviene segnalarlo in fase di prenotazione.', $qv2svvz${}$qv2svvz$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_locale', 'Come segnalo un''esigenza di accessibilità?', $qq2yduh$["sedia a rotelle al ristorante","devo segnalare la sedia a rotelle","accessibilita ristorante disabili","come prenotare con la sedia a rotelle"]$qq2yduh$::jsonb, 'Se qualcuno si muove in sedia a rotelle o con difficoltà motorie conviene segnalarlo in prenotazione: il locale potrà indicare l''accesso e il tavolo più adatti.', $qsxphmi${}$qsxphmi$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_locale', 'Meglio un tavolo all''aperto o dentro?', $q6sv6s5$["tavolo fuori o dentro","posso scegliere il tavolo","si puo scegliere dove sedersi","posso chiedere un tavolo in terrazza"]$q6sv6s5$::jsonb, 'Si può esprimere una preferenza (interno, esterno, terrazza) in fase di prenotazione, ma l''assegnazione dipende dalla disponibilità e dal meteo, quindi non è garantita.', $qzo44mk${}$qzo44mk$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_allergie', 'Come comunico allergie o intolleranze?', $qkwnl8w$["devo dire le allergie","come segnalo un allergia","ho un allergia cosa devo fare","segnalare intolleranze al ristorante"]$qkwnl8w$::jsonb, 'Allergie e intolleranze vanno comunicate in anticipo e, soprattutto, confermate direttamente con il personale di sala o cucina, che conosce ingredienti e preparazioni. In chat non si può dare conferma dell''assenza di allergeni.', $qx5bvfc${}$qx5bvfc$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_allergie', 'Per i celiaci cosa conviene fare?', $qm4bp6r$["sono celiaco cosa devo fare","ristorante per celiaci","come mangiare senza glutine al ristorante","cosa devo dire se sono celiaco"]$qm4bp6r$::jsonb, 'Chi è celiaco dovrebbe segnalarlo al momento della prenotazione e chiedere conferma al personale su opzioni e modalità di preparazione. L''assistente non può assicurare l''assenza di glutine o di contaminazioni.', $qz07n76${}$qz07n76$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_allergie', 'Il locale deve dichiarare gli allergeni?', $qlndett$["obbligo allergeni ristorante","i ristoranti devono indicare gli allergeni","lista allergeni obbligatoria","devono dirmi gli allergeni"]$qlndett$::jsonb, 'In Italia e nell''Unione Europea i locali sono tenuti a poter fornire ai clienti l''informazione sugli allergeni presenti nei piatti. Per un piatto specifico conviene chiedere al personale.', $qu43llp${}$qu43llp$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_menu', 'Cos''è un menu degustazione?', $q3vzk38$["cosa e il menu degustazione","come funziona il menu degustazione","menu degustazione cosa include","cos e un menu degustazione"]$q3vzk38$::jsonb, 'Il menu degustazione è un percorso di più portate scelte dalla cucina, spesso in porzioni ridotte. Composizione e condizioni (anche l''eventuale prenotazione anticipata) le stabilisce il locale.', $q63klqh${}$q63klqh$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_menu', 'Che differenza c''è tra vegetariano e vegano?', $qq2vba3$["differenza vegetariano vegano","vegetariano o vegano cosa cambia","cosa significa vegano","cosa vuol dire vegetariano"]$qq2vba3$::jsonb, 'In genere vegetariano significa senza carne e pesce, mentre vegano esclude anche tutti i prodotti di origine animale, come uova, latte e formaggi. Per i dettagli sui piatti del locale conviene verificare con il personale.', $qg51t42${}$qg51t42$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_menu', 'Il menu cambia?', $qf2qm9g$["il menu cambia con le stagioni","il menu e sempre uguale","piatto del giorno cambia","i piatti cambiano"]$qf2qm9g$::jsonb, 'In molti locali menu e piatti del giorno cambiano con le stagioni e la disponibilità degli ingredienti: per quelli attuali fa fede il menu del locale.', $qg3btpd${}$qg3btpd$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'richiesta_evento', 'Come si organizza una cena di gruppo o un evento?', $qrvjeoc$["organizzare una cena di gruppo","come organizzo una festa al ristorante","cosa serve per un evento","cena aziendale cosa serve"]$qrvjeoc$::jsonb, 'Per eventi e gruppi il locale di solito valuta disponibilità, sala e menu dedicato. Servono data, numero di persone, occasione e se possibile un''idea di budget; poi il locale prepara una proposta.', $qkanau3${}$qkanau3$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'richiesta_evento', 'Posso portare una torta?', $qxuhh83$["posso portare la torta","si puo portare la torta di compleanno","torta da fuori","portare dolci da casa"]$qxuhh83$::jsonb, 'Alcuni locali accettano torte o dolci portati dai clienti, altri no o con condizioni. Conviene chiederlo al locale quando si organizza la festa.', $qlj9c0h${}$qlj9c0h$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_asporto_consegna', 'Che differenza c''è tra asporto e consegna a domicilio?', $qay5oza$["asporto cosa significa","differenza asporto consegna","take away cosa vuol dire","cos e l asporto"]$qay5oza$::jsonb, 'L''asporto (take away) significa ritirare il cibo di persona al locale; la consegna a domicilio è invece portata a casa dal locale o da una piattaforma. Il servizio disponibile e le condizioni dipendono dal locale.', $qxlgjjo${}$qxlgjjo$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_pagamenti', 'Si può dividere il conto?', $qtnirwy$["conto alla romana","si puo fare il conto separato","dividere il conto al ristorante","conti separati"]$qtnirwy$::jsonb, 'La possibilità di dividere il conto o fare conti separati dipende dal locale, conviene segnalarlo in anticipo.', $qtc0cdt${}$qtc0cdt$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_pagamenti', 'Si accettano i buoni pasto?', $qbxz76f$["ticket restaurant accettati","buoni pasto ristorante","accettano i buoni pasto","si possono usare i ticket"]$qbxz76f$::jsonb, 'L''accettazione dei buoni pasto e dei diversi metodi di pagamento varia da locale a locale: va verificata con il locale.', $qmtscnr${}$qmtscnr$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prezzi', 'Perché c''è il coperto?', $qby4xgx$["cos e il coperto","a cosa serve il coperto","il coperto e obbligatorio","coperto cosa comprende"]$qby4xgx$::jsonb, 'Il coperto è una voce che alcuni locali applicano per ogni commensale (servizio di tavola, pane e simili). Se previsto, deve essere indicato nel menu; importo e cosa comprende li stabilisce il locale.', $qat8tps${}$qat8tps$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_posizione', 'Come arrivo se non conosco la zona?', $q6hpuoa$["come trovo il ristorante","come si raggiunge il locale","come arrivare al ristorante","posso farmi mandare la posizione"]$q6hpuoa$::jsonb, 'Posizione, indicazioni e parcheggio sono quelli indicati dal locale: se non li trovi ti conviene chiederli al locale o guardare la sua scheda online.', $q725xds${}$q725xds$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_orari', 'Cosa vuol dire orario della cucina?', $quoekp0$["orario della cucina cosa significa","a che ora chiude la cucina","orario cucina e orario locale","la cucina chiude prima del locale"]$quoekp0$::jsonb, 'In molti locali l''orario in cui la cucina accetta le ordinazioni è diverso dall''orario di apertura. Gli orari esatti sono quelli indicati dal locale.', $q1k72x6${}$q1k72x6$::jsonb);
insert into sector_eval_runs (profile_id, settore, version, scenari_totali, scenari_passati, metriche, gate_passed, note)
