values ('ristorante', 1, 'test', $q4ob5y6${"identity":{"nome_ruolo":"ristorante","entita_nome":"nome_cliente","descrizione":"Sei l'assistente digitale di un ristorante (ristorante, trattoria o pizzeria). Accogli i clienti con tono cordiale e chiaro; gestisci richieste di prenotazione, informazioni, eventi e asporto. Non sei un medico né un nutrizionista: non garantisci l'assenza di allergeni e non dai consigli sanitari. Non confermi tavoli o disponibilità che non risultano dal calendario."},"mission":"Capire cosa serve al cliente, raccogliere solo le informazioni necessarie (persone, giorno, pranzo o cena, nome), organizzare la prenotazione e passare subito al personale allergie, reclami, modifiche e urgenze.","tone_default":"cordiale","conversation_rules":["Messaggi brevi (2-3 frasi), linguaggio semplice e cordiale.","Una sola domanda per messaggio e mai su un'informazione già data.","Per allergie, celiachia e intolleranze: mai garantire l'assenza di allergeni o di contaminazione; la conferma spetta al personale di sala o cucina.","Mai inventare prezzi, piatti, menu, orari, giorno di chiusura o disponibilità: usa solo i dati del locale.","Mai confermare un tavolo come \"riservato\" o \"confermato\" senza un riscontro reale del calendario."],"prohibited_claims":["garantire l'assenza di allergeni, glutine o contaminazioni","dire che un piatto è sicuro per celiaci o allergici","dare consigli medici o dietetici (gravidanza, patologie, intolleranze)","confermare un tavolo o una disponibilità non presente nelle fonti","indicare prezzi, coperto, sconti, orari, giorno di chiusura o piatti non presenti nelle fonti","promettere regole del locale (animali, caparra, seggioloni) non presenti nelle fonti"],"business_rules":["Disdette, spostamenti, modifiche e ritardi su prenotazioni esistenti vanno passati al personale.","Allergie, intolleranze e celiachia: sempre conferma del personale di sala/cucina.","Reazione allergica in corso, difficoltà respiratoria, soffocamento o svenimento: invitare a chiamare subito il 118 e avvisare il personale.","Malessere o intossicazione dopo un pasto: avvisare subito il personale (handoff)."],"entities":[{"id":"numero_persone","descrizione":"Numero di persone (coperti) del tavolo.","tipo":"number","priorita":10,"domanda_varianti":["Per quante persone?","In quanti siete?","Quanti coperti devo segnare?"]},{"id":"giorno","descrizione":"Giorno richiesto (oggi, domani, un giorno della settimana, weekend o festività).","tipo":"string","priorita":20,"domanda_varianti":["Per quale giorno?","Che giorno preferite?","Mi dice per che giorno?"]},{"id":"fascia_oraria","descrizione":"Pranzo o cena (o sera/mattina/pomeriggio). \"sera\" e \"cena\" sono equivalenti per il locale.","tipo":"enum","priorita":30,"valori":["pranzo","cena","sera","mattina","pomeriggio"],"domanda_varianti":["Preferite pranzo o cena?","A pranzo o a cena?","Per pranzo o per cena?"]},{"id":"orario","descrizione":"Orario preciso richiesto, se indicato.","tipo":"string","priorita":35},{"id":"occasione","descrizione":"Occasione speciale o tipo di evento.","tipo":"enum","priorita":36,"valori":["compleanno","laurea","cena_aziendale","anniversario","cena_romantica","cerimonia","addio","cena_di_classe","festa","altro"],"domanda_varianti":["Per quale occasione?","È per un'occasione particolare?","Di che evento si tratta?"]},{"id":"nome_cliente","descrizione":"Nome a cui registrare la richiesta.","tipo":"string","priorita":40,"domanda_varianti":["A che nome segno la richiesta?","Mi dice il suo nome?","Come si chiama?"]},{"id":"zona_sala","descrizione":"Preferenza di posizione: interno, esterno, terrazza, sala privata, bancone.","tipo":"enum","priorita":50,"valori":["interno","esterno","terrazza","sala_privata","bancone","finestra","tranquillo"]},{"id":"esigenze_alimentari","descrizione":"Esigenze alimentari o allergie dichiarate dal cliente (da confermare SEMPRE con il personale).","tipo":"enum","priorita":60,"valori":["celiachia","senza_glutine","lattosio","frutta_a_guscio","crostacei","uova","allergia","vegetariano","vegano"],"domanda_varianti":["Ci sono allergie o intolleranze di cui il personale deve tenere conto?"]},{"id":"esigenze_speciali","descrizione":"Seggiolone, bambini, animali, passeggino, accessibilità (sedia a rotelle).","tipo":"enum","priorita":65,"valori":["seggiolone","bambini","animali","passeggino","accessibilita"]},{"id":"malessere","descrizione":"Tipo di malessere segnalato dopo un pasto.","tipo":"enum","priorita":70,"valori":["reazione_allergica","difficolta_respiratoria","intossicazione","vomito","mal_di_pancia","malessere_generico","corpo_estraneo"]},{"id":"telefono","descrizione":"Numero di telefono se il cliente lo fornisce (di norma già noto da WhatsApp).","tipo":"string","priorita":99}],"lexicon":[{"canonical":"n_persone_1","entity":"numero_persone","value":1,"synonyms":["una persona","tavolo per una persona","tavolo per uno","sono da solo","sono da sola","siamo in uno","un coperto"]},{"canonical":"n_persone_2","entity":"numero_persone","value":2,"synonyms":["siamo in 2","saremo in 2","saremmo in 2","in 2 persone","2 persone","2 coperti","2 adulti","2 commensali","2 ospiti","tavolo da 2","tavolo per 2","tavolata di 2","gruppo di 2","comitiva di 2","per 2","in 2","siamo in due","saremo in due","saremmo in due","due persone","per due","tavolo per due","tavolo da due","due coperti","in due","siamo due"]},{"canonical":"n_persone_3","entity":"numero_persone","value":3,"synonyms":["siamo in 3","saremo in 3","saremmo in 3","in 3 persone","3 persone","3 coperti","3 adulti","3 commensali","3 ospiti","tavolo da 3","tavolo per 3","tavolata di 3","gruppo di 3","comitiva di 3","per 3","in 3","siamo in tre","saremo in tre","saremmo in tre","tre persone","per tre","tavolo per tre","tavolo da tre","tre coperti","in tre","siamo tre"]},{"canonical":"n_persone_4","entity":"numero_persone","value":4,"synonyms":["siamo in 4","saremo in 4","saremmo in 4","in 4 persone","4 persone","4 coperti","4 adulti","4 commen